// The upcoming event, as the admin dashboard (Upcoming event tab) sets it.
// You do not edit this file. Every function answers with the dashboard's value when there is one,
// and with the value written in src/site/upcomingConfig.js when the dashboard did not change it.
//
//   eventType()      'hackathon' | 'workshop' | 'online'
//   eventName()      the name ('' = no name yet: the card stays a mystery)
//   eventDetails()   the detail boxes of the chosen type (Format, Rounds ... / Topic, Speaker ... / Platform, Host ...)
//   eventPoints()    the description points  [{ t, d }]
//   eventLink()      where the Register button goes ('' = the site's own /register page)
//   bannerUrls()     the uploaded banners (empty = the pictures in src/assets/upcoming/)
//   logoUrl()        the small logo of the popup ('' = none)
//   popupDelayMs()   how long after opening the site the popup may come
//   popupDescLive()  one line of own words for the popup ('' = the usual words)
import { liveValue } from './liveSettings';
import * as C from './upcomingConfig';

export const TYPES = ['hackathon', 'workshop', 'online'];
const FILE_TYPE = TYPES.includes(C.EVENT_TYPE) ? C.EVENT_TYPE : 'hackathon';

const plain = (o) => (o && typeof o === 'object' && !Array.isArray(o) ? o : null);

export function eventType() {
  const v = liveValue('eventType', C.EVENT_TYPE);
  return TYPES.includes(v) ? v : FILE_TYPE;
}

// '' is a real answer here (the admin cleared the name on purpose), so only "nothing saved" falls back to the code file
export function eventName() {
  const v = liveValue('eventName', C.EVENT_NAME);
  return typeof v === 'string' ? v.trim() : String(C.EVENT_NAME || '').trim();
}

export function eventDetails() {
  const type = eventType();
  const per = plain(liveValue('eventDetails', null));
  if (per && plain(per[type])) return per[type];
  if (!per) {
    // the older boxes of the Events tab (one list for the event type of the code file)
    const old = plain(liveValue('details', null));
    if (old && type === FILE_TYPE) return old;
  }
  return (C.DETAILS && C.DETAILS[type]) || {};
}

export function eventPoints() {
  const v = liveValue('eventPoints', null);
  if (!Array.isArray(v)) return [];
  return v.filter((p) => p && typeof p.t === 'string' && p.t.trim()).slice(0, 8).map((p) => ({ t: p.t, d: typeof p.d === 'string' ? p.d : '' }));
}

export function eventLink() {
  const v = liveValue('eventLink', '');
  return typeof v === 'string' ? v : '';
}

const MEDIA_ID = /^e-(b[1-4]|logo)$/;
const VERSION = /^[a-z0-9]{1,16}$/;
export const mediaUrl = (id, v) => `/api/people?photo=${encodeURIComponent(id)}&v=${encodeURIComponent(v)}`;

let lastBanners = { key: '', list: [] };
export function bannerUrls() {
  const v = liveValue('eventBanners', null);
  const list = Array.isArray(v) ? v.filter((b) => b && MEDIA_ID.test(String(b.id)) && VERSION.test(String(b.v))).slice(0, 4).map((b) => mediaUrl(b.id, b.v)) : [];
  const key = list.join('|');
  if (key !== lastBanners.key) lastBanners = { key, list };
  return lastBanners.list;   // the same array while nothing changes, so React effects do not run again
}

export function logoUrl() {
  const v = plain(liveValue('popupLogo', null));
  return v && VERSION.test(String(v.v)) ? mediaUrl('e-logo', v.v) : '';
}

export function popupDelayMs() {
  const s = Number(liveValue('popupDelay', (Number(C.POPUP_DELAY) || 0) / 1000));
  return Math.round(Math.min(120, Math.max(0, Number.isFinite(s) ? s : 0)) * 1000);
}

export function popupDescLive() {
  const v = liveValue('popupDesc', '');
  return typeof v === 'string' ? v.trim() : '';
}
